{
  "version": 1,
  "parent": {
    "file": "parent.mjs",
    "calls": ["order-id", "intake", "fraud", "customer-action", "order-progress", "fulfilment", "cancellation", "statuses", "notices"],
    "effects": [],
    "humanTasks": []
  },
  "modules": {
    "order-id": {
      "file": "modules/order-id.mjs",
      "purpose": "normalise an order id read anywhere (SPEC-E 3.1); pure, stateless",
      "rules": ["3.1"],
      "input": {
        "type": "object",
        "required": ["raw"],
        "properties": { "raw": { "type": ["string", "null"], "maxLength": 400 } }
      },
      "output": {
        "type": "object",
        "required": ["orderId"],
        "properties": { "orderId": { "type": ["string", "null"], "maxLength": 80 } }
      },
      "effects": [],
      "humanTasks": [],
      "timers": false,
      "calls": [],
      "reads": []
    },
    "intake": {
      "file": "modules/intake.mjs",
      "purpose": "one order: duplicate check, allocation, edition in force at p, amounts, orders.create (R1)",
      "rules": ["R1.1", "R1.2", "R1.3", "R1.4", "3.1"],
      "input": {
        "type": "object",
        "required": ["op"],
        "properties": {
          "op": { "enum": ["placed", "resume"] },
          "order": {
            "type": "object",
            "required": ["orderId", "customerId", "placedAt", "items"],
            "properties": {
              "orderId": { "type": "string", "minLength": 1, "maxLength": 80 },
              "customerId": { "type": "string", "minLength": 1, "maxLength": 80 },
              "placedAt": { "type": "string", "minLength": 1, "maxLength": 40 },
              "currency": { "type": "string", "minLength": 3, "maxLength": 3 },
              "items": {
                "type": "array",
                "minItems": 1,
                "maxItems": 50,
                "items": {
                  "type": "object",
                  "required": ["sku", "qty"],
                  "properties": {
                    "sku": { "type": "string", "minLength": 1, "maxLength": 80 },
                    "qty": { "type": "integer", "minimum": 1 }
                  }
                }
              }
            }
          },
          "records": { "type": "object" }
        }
      },
      "output": {
        "type": "object",
        "required": ["status", "duplicate", "busy"],
        "properties": {
          "status": { "enum": ["new", "allocating", "recording", "recorded"] },
          "duplicate": { "type": "boolean" },
          "busy": { "type": "boolean" },
          "orderId": { "type": ["string", "null"], "maxLength": 80 },
          "customerId": { "type": ["string", "null"], "maxLength": 80 },
          "placedAt": { "type": ["string", "null"], "maxLength": 40 },
          "currency": { "type": ["string", "null"], "maxLength": 3 },
          "edition": { "type": ["string", "null"], "maxLength": 80 },
          "totalMinor": { "type": ["integer", "null"] },
          "fulfilments": {
            "type": ["array", "null"],
            "maxItems": 20,
            "items": {
              "type": "object",
              "required": ["fulfilmentId", "location", "available", "items", "amountMinor"],
              "properties": {
                "fulfilmentId": { "type": "string", "minLength": 1, "maxLength": 80 },
                "location": { "type": ["string", "null"], "maxLength": 40 },
                "available": { "type": "boolean" },
                "items": { "type": "array", "maxItems": 50 },
                "amountMinor": { "type": "integer" }
              }
            }
          }
        }
      },
      "effects": ["inventory.allocate", "orders.create"],
      "humanTasks": [],
      "timers": false,
      "calls": ["order-id"],
      "reads": []
    },
    "fraud": {
      "file": "modules/fraud.mjs",
      "purpose": "one order: fraud.check, the review task and its deadline, the clearing (R2)",
      "rules": ["R2.1", "R2.2", "S3", "3.4"],
      "input": {
        "type": "object",
        "required": ["op"],
        "properties": {
          "op": { "enum": ["start", "stop"] },
          "orderId": { "type": "string", "minLength": 1, "maxLength": 80 },
          "placedAt": { "type": "string", "minLength": 1, "maxLength": 40 },
          "edition": { "type": "string", "minLength": 1, "maxLength": 80 }
        }
      },
      "output": {
        "type": "object",
        "required": ["state", "busy"],
        "properties": {
          "state": { "enum": ["idle", "checking", "review", "cleared", "cancel", "stopped"] },
          "at": { "type": ["string", "null"], "maxLength": 40 },
          "reason": { "enum": ["fraud", "fraud-review-timeout", null] },
          "busy": { "type": "boolean" }
        }
      },
      "effects": ["fraud.check"],
      "humanTasks": ["fraudReview"],
      "timers": true,
      "calls": [],
      "reads": []
    },
    "customer-action": {
      "file": "modules/customer-action.mjs",
      "purpose": "one order with unavailable items: action-required, the customer deadline D, amend / cancel / timeout (R3)",
      "rules": ["R3.1", "R3.2", "S1"],
      "input": {
