}

function finish(s, ctx) {
  if (s.failing) {
    s.end = 'failed';
    s.endedAt = ctx.now;
    ctx.call('statuses', s.orderId, { op: 'set', fulfilmentId: ctx.key, status: 'failed' });
    ctx.call('notices', s.orderId, { op: 'send', template: 'fulfilment-failed', about: ctx.key, customerId: s.customerId });
